Definition prep_seg2_W (lo : Z) (sp : word) (A b : Z) (es : list mbe) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -88); (A, A + 24); (b + 8, b + 64); (mb_lasta b es, mb_lasta b es + 8)]%Z.

Definition prep_seg2_stmt : Prop := forall (res b A : Z) (es : list mbe) (insz n oe1 lo : Z) (j64 j80 j48 junkB : list byte)
    (sp : word) gp tp (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s4 s8 s10 s11 t3 t4 t5 t6 : word)
    (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) fc (m : mem),
  MBraw m b es (mb_out b es insz) insz (mb_outpos es insz) oe1 -> mb_ok es insz -> mb_need es insz n = true -> 1 <= n -> insz + n <= 2^30 ->
  prep_frame m (bv_unsigned sp + -176) j64 (wz (bv_unsigned sp + -112)) (wz (bv_unsigned sp + -112)) j80 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav ->
  alloc_frame m (bv_unsigned sp + -240) j48 n ->
  rw_cells usegs m A [CB (Z.to_nat (mb_block_size (mb_grow es insz n))) junkB] -> rblock_range A (mb_block_size (mb_grow es insz n)) ->
  (forall x' s', In (x', s') es -> A + mb_block_size (mb_grow es insz n) <= x' \/ x' + 24 + s' <= A) ->
  stk usegs m lo (bv_unsigned sp + -240) -> lo + 240 <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= b -> bv_unsigned sp mod 16 = 0 ->
  mem_inv usegs m ->
  evt usegs (prep_attail_post (bv_unsigned sp + -176) gp tp s10 s11 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav F fc res b es insz n A lo
